import Foundation

/// A form of the onboarding packet. The PDFs are generated by tools/generate_forms.py.
struct PacketForm: Identifiable, Hashable {
    let id: String
    let title: String
    let code: String
    let summary: String
    let fileName: String
    let symbol: String
}

enum PacketCatalog {
    static let title = "Personal account onboarding"

    static let forms: [PacketForm] = [
        PacketForm(
            id: "account-opening",
            title: "Account Opening Application",
            code: "QSB-AO-01",
            summary: "Personal details, address, employment, account choice and declaration. Signed by the customer.",
            fileName: "account-opening-application.pdf",
            symbol: "person.text.rectangle"
        ),
        PacketForm(
            id: "privacy-consent",
            title: "Privacy and Communications Consent",
            code: "QSB-PC-02",
            summary: "Required consents and optional marketing preferences. Signed by the customer.",
            fileName: "privacy-and-communications-consent.pdf",
            symbol: "hand.raised"
        ),
        PacketForm(
            id: "identity-verification",
            title: "Identity Verification Record",
            code: "QSB-IV-03",
            summary: "Identity and address documents seen by the staff member. Signed by the customer and the staff member.",
            fileName: "identity-verification-record.pdf",
            symbol: "checkmark.shield"
        ),
    ]
}
